--
-- Table structure for table `demande`
--

DROP TABLE IF EXISTS `demande`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `demande` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `numero_suivi` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `type_demande` varchar(20) NOT NULL,
  `objet` varchar(300) NOT NULL,
  `message` text NOT NULL,
  `organisme` varchar(160) DEFAULT NULL,
  `pays` varchar(80) DEFAULT NULL,
  `projet_id` bigint(20) unsigned DEFAULT NULL,
  `nom_contact` varchar(160) DEFAULT NULL,
  `courriel` varchar(254) DEFAULT NULL,
  `telephone` varchar(30) DEFAULT NULL,
  `base` varchar(30) NOT NULL,
  `consentement_donne` tinyint(1) NOT NULL DEFAULT 0,
  `texte_information_version` varchar(60) NOT NULL,
  `statut` varchar(20) NOT NULL DEFAULT 'recue',
  `priorite` smallint(6) DEFAULT NULL,
  `affectee_a` bigint(20) unsigned DEFAULT NULL,
  `recue_le` datetime NOT NULL DEFAULT current_timestamp(),
  `premiere_reponse_le` datetime DEFAULT NULL,
  `cloturee_le` datetime DEFAULT NULL,
  `conserver_jusqu_au` date NOT NULL,
  `anonymisee_le` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `numero_suivi` (`numero_suivi`),
  KEY `projet_id` (`projet_id`),
  KEY `affectee_a` (`affectee_a`),
  CONSTRAINT `demande_ibfk_1` FOREIGN KEY (`projet_id`) REFERENCES `projet` (`id`),
  CONSTRAINT `demande_ibfk_2` FOREIGN KEY (`affectee_a`) REFERENCES `utilisateur` (`id`),
  CONSTRAINT `chk_demande_numero_suivi` CHECK (`numero_suivi` regexp '^DEM-[0-9]{4}-[A-Z0-9]{6}$'),
  CONSTRAINT `chk_demande_type_demande` CHECK (`type_demande` in ('contact','investisseur','partenaire','diaspora','autre')),
  CONSTRAINT `chk_demande_message` CHECK (char_length(`message`) <= 4000),
  CONSTRAINT `chk_demande_base` CHECK (`base` in ('consentement','mission_interet_public','obligation_legale')),
  CONSTRAINT `chk_demande_statut` CHECK (`statut` in ('recue','qualifiee','affectee','en_traitement','repondue','cloturee','rejetee')),
  CONSTRAINT `chk_demande_priorite_borne` CHECK (`priorite` between 1 and 3),
  CONSTRAINT `chk_demande_consentement` CHECK (`base` <> 'consentement' or `consentement_donne` <> 0),
  CONSTRAINT `chk_demande_conservation` CHECK (`conserver_jusqu_au` > cast(`recue_le` as date)),
