CREATE TABLE `projet` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `slug` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `titre` varchar(120) NOT NULL,
  `secteur` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `resume` text DEFAULT NULL,
  `description_technique` mediumtext DEFAULT NULL,
  `description_publique` tinyint(1) NOT NULL DEFAULT 0,
  `besoin` text DEFAULT NULL,
  `besoin_source_id` bigint(20) unsigned DEFAULT NULL,
  `statut` varchar(30) NOT NULL DEFAULT 'idee_identifiee',
  `statut_mis_a_jour_le` datetime NOT NULL DEFAULT current_timestamp(),
  `motif_suspension` text DEFAULT NULL,
  `avancement_pct` decimal(5,2) DEFAULT NULL,
  `avancement_source_id` bigint(20) unsigned DEFAULT NULL,
  `avancement_date` date DEFAULT NULL,
  `service_responsable` varchar(160) DEFAULT NULL,
  `responsable_id` bigint(20) unsigned DEFAULT NULL,
  `visible_catalogue` tinyint(1) NOT NULL DEFAULT 1,
  `motif_retrait` text DEFAULT NULL,
  `etat` varchar(20) NOT NULL DEFAULT 'brouillon',
  `cree_le` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  UNIQUE KEY `slug` (`slug`),
  KEY `secteur` (`secteur`),
  KEY `besoin_source_id` (`besoin_source_id`),
  KEY `avancement_source_id` (`avancement_source_id`),
  KEY `responsable_id` (`responsable_id`),
  CONSTRAINT `projet_ibfk_1` FOREIGN KEY (`secteur`) REFERENCES `secteur` (`code`),
  CONSTRAINT `projet_ibfk_2` FOREIGN KEY (`besoin_source_id`) REFERENCES `source` (`id`),
  CONSTRAINT `projet_ibfk_3` FOREIGN KEY (`avancement_source_id`) REFERENCES `source` (`id`),
  CONSTRAINT `projet_ibfk_4` FOREIGN KEY (`responsable_id`) REFERENCES `utilisateur` (`id`),
  CONSTRAINT `chk_projet_code` CHECK (`code` regexp '^PRJ-[0-9]{4}-[0-9]{3,}$'),
  CONSTRAINT `chk_projet_slug` CHECK (`slug` regexp '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT `chk_projet_resume` CHECK (char_length(`resume`) <= 500),
  CONSTRAINT `chk_projet_statut` CHECK (`statut` in ('idee_identifiee','etude_en_cours','dossier_en_preparation','pret_a_etre_soumis','financement_recherche','finance','en_execution','acheve','suspendu')),
  CONSTRAINT `chk_projet_etat` CHECK (`etat` in ('brouillon','en_revue','approuve','publie','retire')),
  CONSTRAINT `chk_projet_avancement_borne` CHECK (`avancement_pct` between 0 and 100),
  CONSTRAINT `chk_projet_besoin_source` CHECK (`besoin` is null or `besoin_source_id` is not null),
  CONSTRAINT `chk_projet_motif_suspension` CHECK (`statut` <> 'suspendu' or `motif_suspension` is not null),
  CONSTRAINT `chk_projet_avancement_source` CHECK (`avancement_pct` is null or `avancement_source_id` is not null and `avancement_date` is not null),
  CONSTRAINT `chk_projet_avancement_statut` CHECK (`avancement_pct` is null or `statut` in ('en_execution','acheve','suspendu')),
  CONSTRAINT `chk_projet_retrait` CHECK (`visible_catalogue` <> 0 or `motif_retrait` is not null)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
