  `demande_par` bigint(20) unsigned NOT NULL,
  `demande_le` datetime NOT NULL DEFAULT current_timestamp(),
  `motif` text DEFAULT NULL,
  `piece_id` bigint(20) unsigned DEFAULT NULL,
  `decision` varchar(20) NOT NULL DEFAULT 'en_attente',
  `valide_par` bigint(20) unsigned DEFAULT NULL,
  `valide_le` datetime DEFAULT NULL,
  `applique_le` datetime DEFAULT NULL,
  `attente_projet` bigint(20) unsigned GENERATED ALWAYS AS (if(`decision` = 'en_attente',`projet_id`,NULL)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `projet_transition_une_seule_en_attente` (`attente_projet`),
  KEY `projet_id` (`projet_id`),
  KEY `de_statut` (`de_statut`,`vers_statut`),
  KEY `demande_par` (`demande_par`),
  KEY `piece_id` (`piece_id`),
  KEY `valide_par` (`valide_par`),
  CONSTRAINT `projet_transition_ibfk_1` FOREIGN KEY (`projet_id`) REFERENCES `projet` (`id`),
  CONSTRAINT `projet_transition_ibfk_2` FOREIGN KEY (`de_statut`, `vers_statut`) REFERENCES `transition_autorisee` (`de_statut`, `vers_statut`),
  CONSTRAINT `projet_transition_ibfk_3` FOREIGN KEY (`demande_par`) REFERENCES `utilisateur` (`id`),
  CONSTRAINT `projet_transition_ibfk_4` FOREIGN KEY (`piece_id`) REFERENCES `projet_piece` (`id`),
  CONSTRAINT `projet_transition_ibfk_5` FOREIGN KEY (`valide_par`) REFERENCES `utilisateur` (`id`),
  CONSTRAINT `chk_projet_transition_decision` CHECK (`decision` in ('en_attente','approuve','renvoye')),
  CONSTRAINT `chk_projet_transition_separation` CHECK (`valide_par` is null or `valide_par` <> `demande_par`),
  CONSTRAINT `chk_projet_transition_coherence` CHECK (`decision` = 'en_attente' = (`valide_par` is null)),
  CONSTRAINT `chk_projet_transition_motif` CHECK (`vers_statut` <> 'suspendu' or `motif` is not null),
  CONSTRAINT `chk_projet_transition_application` CHECK (`applique_le` is null or `decision` = 'approuve')
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
