CREATE TABLE `publication` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `objet_type` varchar(20) NOT NULL,
  `objet_id` bigint(20) unsigned NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `instantane` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`instantane`)),
  `validation_id` bigint(20) unsigned NOT NULL,
  `publie_par` bigint(20) unsigned NOT NULL,
  `publie_le` datetime NOT NULL DEFAULT current_timestamp(),
  `retire_le` datetime DEFAULT NULL,
  `motif_retrait` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `publication_version` (`objet_type`,`objet_id`,`version`),
  UNIQUE KEY `publication_validation_unique` (`validation_id`),
  KEY `publication_courante` (`objet_type`,`objet_id`,`retire_le`),
  KEY `publie_par` (`publie_par`),
  CONSTRAINT `publication_ibfk_1` FOREIGN KEY (`validation_id`) REFERENCES `validation_demande` (`id`),
  CONSTRAINT `publication_ibfk_2` FOREIGN KEY (`publie_par`) REFERENCES `utilisateur` (`id`),
  CONSTRAINT `chk_publication_objet_type` CHECK (`objet_type` in ('contenu','projet','document','elu','partenaire','localite','equipement','media')),
  CONSTRAINT `chk_publication_version` CHECK (`version` > 0),
  CONSTRAINT `chk_publication_retrait` CHECK (`retire_le` is null or `motif_retrait` is not null)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
